// Owns: making src/content/atlas-table.ts from assets/atlas.json, so the sprite table has one source (rule C3).
import fs from 'node:fs';
import path from 'node:path';

export function generateAtlasTable(root) {
  const table = JSON.parse(fs.readFileSync(path.join(root, 'assets/atlas.json'), 'utf8'));
  const rows = Object.entries(table)
    .filter(([name]) => !name.startsWith('_'))
    .map(([name, rect]) => `  ${name}: [${rect.join(', ')}],`);
  const text = [
    '// Owns: every sprite in the atlas. Generated by tools/gen-atlas-table.mjs from assets/atlas.json: do not edit.',
    'export type AtlasSprite = readonly [x: number, y: number, width: number, height: number, px: number, py: number];',
    '',
    'export const ATLAS_SPRITES: Readonly<Record<string, AtlasSprite>> = {',
    ...rows,
    '};',
    '',
  ].join('\n');
  fs.writeFileSync(path.join(root, 'src/content/atlas-table.ts'), text);
}
